L26_1 = "\236\154\176\236\136\152\237\149\156 \236\157\184\236\158\172\235\147\164\236\157\128 \236\157\180\236\160\156 \236\157\180\234\179\179\236\151\144\236\132\156 \236\130\172\236\158\165\235\139\152\234\179\188 \235\167\140\235\130\152\234\178\140 \235\144\152\234\178\160\235\132\164\236\154\148."
L25_1.Text_KOREA = L26_1
L26_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L25_1.StringValue = L26_1
L26_1 = "\228\187\138\229\190\140\227\128\129\227\129\147\227\129\147\227\129\167\229\132\170\231\167\128\227\129\170\228\186\186\230\157\144\227\129\168\229\135\186\228\188\154\227\129\136\227\130\139\227\129\168\230\128\157\227\129\132\227\129\190\227\129\153\227\128\130"
