L26_1 = "\230\130\168\229\143\175\228\187\165\229\156\168\232\191\153\233\135\140\228\188\154\232\167\129\228\188\152\231\167\128\231\154\132\228\186\186\230\137\141\227\128\130"
L25_1.Text_SCN = L26_1
L26_1 = "\228\185\139\229\190\140\229\132\170\231\167\128\231\154\132\228\186\186\230\137\141\233\131\189\230\156\131\229\156\168\233\128\153\232\163\161\229\146\140\232\128\129\233\151\134\232\166\139\233\157\162\229\150\148\239\188\129"
L25_1.Text_TWN = L26_1
L26_1 = "\224\184\132\224\184\184\224\184\147\224\184\170\224\184\178\224\184\161\224\184\178\224\184\163\224\184\150\224\184\155\224\184\163\224\184\176\224\184\138\224\184\184\224\184\161\224\184\129\224\184\177\224\184\154\224\184\158\224\184\153\224\184\177\224\184\129\224\184\135\224\184\178\224\184\153\224\184\132\224\184\153\224\185\128\224\184\129\224\185\136\224\184\135\224\184\130\224\184\173\224\184\135\224\184\132\224\184\184\224\184\147\224\185\132\224\184\148\224\185\137\224\184\151\224\184\181\224\185\136\224\184\153\224\184\181\224\185\136"
L25_1.Text_THA = L26_1
L26_1 = "T\225\186\161i \196\145\195\162y, ng\195\160i c\195\179 th\225\187\131 t\225\187\149 ch\225\187\169c cu\225\187\153c h\225\187\141p v\225\187\155i c\195\161c nh\195\162n vi\195\170n t\195\160i n\196\131ng."
