L26_1.EventType = "MESSAGE_BOX"
L27_1 = "\236\176\184, \236\139\160\234\183\156 \236\157\184\235\160\165 \236\177\132\236\154\169\236\151\144 \235\140\128\237\149\156 \234\178\176\236\158\172\235\165\188 \234\184\176\235\139\164\235\166\172\234\179\160 \236\158\136\235\138\148\235\141\176\n\234\185\156\235\185\161 \236\158\138\234\179\160\236\158\136\236\151\136\235\132\164\236\154\148."
