L27_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L26_1.StringValue = L27_1
L27_1 = "\227\129\130\227\129\163\227\128\129\230\150\176\232\166\143\228\186\186\230\157\144\230\142\161\231\148\168\227\129\174\230\177\186\232\163\129\227\130\146\229\190\133\227\129\163\227\129\166\227\129\132\227\129\159\227\129\147\227\129\168\227\130\146\n\227\129\153\227\129\163\227\129\139\227\130\138\229\191\152\227\130\140\227\129\166\227\129\132\227\129\190\227\129\151\227\129\159\227\128\130"
L26_1.Text_JPN = L27_1
L27_1 = [[
Oh, I almost forgot. I need your approval
for new recruitment.]]
L26_1.Text_ENG = L27_1
L27_1 = "\229\149\138\239\188\140\230\136\145\229\183\174\231\130\185\229\191\152\228\186\134\239\188\140\230\156\137\228\184\170\230\150\176\232\129\140\229\145\152\231\154\132\233\155\135\228\189\163\233\161\185\231\155\174\n\230\173\163\231\173\137\230\130\168\229\174\161\230\137\185\229\145\162\227\128\130"
L26_1.Text_SCN = L27_1
L27_1 = "\229\176\141\228\186\134\239\188\140\233\155\135\229\130\173\230\150\176\229\147\161\229\183\165\231\154\132\228\186\139\233\130\132\229\156\168\231\173\137\232\128\129\233\151\134\231\162\186\232\170\141\229\145\162\239\188\129\n\229\183\174\233\187\158\229\191\152\232\168\152\228\186\134\239\188\129"
L26_1.Text_TWN = L27_1
L27_1 = "\224\184\173\224\185\138\224\184\176 \224\185\128\224\184\129\224\184\183\224\184\173\224\184\154\224\184\165\224\184\183\224\184\161\224\185\128\224\184\165\224\184\162 \224\184\137\224\184\177\224\184\153\224\184\149\224\185\137\224\184\173\224\184\135\224\185\131\224\184\171\224\185\137\224\184\132\224\184\184\224\184\147\224\184\173\224\184\153\224\184\184\224\184\161\224\184\177\224\184\149\224\184\180\n\224\184\129\224\184\178\224\184\163\224\184\170\224\184\163\224\184\163\224\184\171\224\184\178\224\184\158\224\184\153\224\184\177\224\184\129\224\184\135\224\184\178\224\184\153\224\184\132\224\184\163\224\184\177\224\185\137\224\184\135\224\185\131\224\184\171\224\184\161\224\185\136"
L26_1.Text_THA = L27_1
L27_1 = "\225\187\146, t\195\180i g\225\186\167n nh\198\176 qu\195\170n m\225\186\165t. T\195\180i c\225\186\167n ng\195\160i ph\195\170 duy\225\187\135t\ncho tuy\225\187\131n d\225\187\165ng m\225\187\155i."
L26_1.Text_VTN = L27_1
L27_1 = "Ach, das h\195\164tte ich fast vergessen. Ich brauche Ihre Genehmigung f\195\188r neue Rekrutierungen."
