L44_1.Text_TWN = L45_1
L45_1 = "\224\184\137\224\184\177\224\184\153\224\184\132\224\185\137\224\184\153\224\184\158\224\184\154\224\185\129\224\184\156\224\184\153\224\184\170\224\184\153\224\184\177\224\184\154\224\184\170\224\184\153\224\184\184\224\184\153\224\184\129\224\184\178\224\184\163\224\184\170\224\184\163\224\184\163\224\184\171\224\184\178\224\184\170\224\184\179\224\184\171\224\184\163\224\184\177\224\184\154\224\184\154\224\184\163\224\184\180\224\184\169\224\184\177\224\184\151\224\184\151\224\184\178\224\184\170\224\184\129\224\185\140\224\184\159\224\184\173\224\184\163\224\185\140\224\184\170\224\184\130\224\184\153\224\184\178\224\184\148\224\185\128\224\184\165\224\185\135\224\184\129\224\185\129\224\184\154\224\184\154\224\185\128\224\184\163\224\184\178"
L44_1.Text_THA = L45_1
L45_1 = "T\195\180i \196\145\195\163 ph\195\161t hi\225\187\135n ra m\225\187\153t k\225\186\191 ho\225\186\161ch h\225\187\151 tr\225\187\163 tuy\225\187\131n d\225\187\165ng cho c\195\161c c\195\180ng ty TASKFORCE nh\225\187\143 nh\198\176 c\225\187\167a ch\195\186ng ta. "
