L45_1.Text_ENG = L46_1
L46_1 = "\229\143\175\228\187\165\231\148\168\228\189\142\229\187\137\231\154\132\228\187\183\230\160\188\230\139\155\229\139\159\230\150\176\232\129\140\229\145\152\227\128\130\n\232\181\132\233\135\145\229\183\178\231\187\143\229\135\134\229\164\135\229\165\189\228\186\134\239\188\140\230\130\168\229\143\170\233\156\128\232\166\129\230\137\185\229\135\134\229\176\177\229\143\175\228\187\165\228\186\134\227\128\130"
L45_1.Text_SCN = L46_1
L46_1 = "\229\143\175\228\187\165\231\148\168\228\190\191\229\174\156\231\154\132\229\131\185\230\160\188\230\139\155\229\139\159\230\150\176\229\147\161\229\183\165\227\128\130\n\232\179\135\233\135\145\233\131\189\229\183\178\231\182\147\229\176\177\231\183\146\239\188\140\229\176\177\231\173\137\232\128\129\233\151\134\228\184\128\229\143\165\232\169\177\229\155\137\239\188\129"
L45_1.Text_TWN = L46_1
L46_1 = "\224\185\128\224\184\163\224\184\178\224\185\131\224\184\138\224\185\137\224\184\161\224\184\177\224\184\153\224\184\170\224\184\163\224\184\163\224\184\171\224\184\178\224\184\158\224\184\153\224\184\177\224\184\129\224\184\135\224\184\178\224\184\153\224\185\132\224\184\148\224\185\137\224\185\131\224\184\153\224\184\163\224\184\178\224\184\132\224\184\178\224\184\150\224\184\185\224\184\129\n\224\185\128\224\184\163\224\184\178\224\184\161\224\184\181\224\184\151\224\184\184\224\184\153\224\184\158\224\184\163\224\185\137\224\184\173\224\184\161\224\185\129\224\184\165\224\185\137\224\184\167 \224\184\149\224\184\173\224\184\153\224\184\153\224\184\181\224\185\137\224\185\129\224\184\132\224\185\136\224\184\149\224\185\137\224\184\173\224\184\135\224\185\131\224\184\171\224\185\137\224\184\132\224\184\184\224\184\147\224\184\173\224\184\153\224\184\184\224\184\161\224\184\177\224\184\149\224\184\180"
L45_1.Text_THA = L46_1
L46_1 = "Ch\195\186ng ta c\195\179 th\225\187\131 s\225\187\173 d\225\187\165ng n\195\179 \196\145\225\187\131 tuy\225\187\131n d\225\187\165ng nh\195\162n vi\195\170n v\225\187\155i chi ph\195\173 th\225\186\165p h\198\161n.\nCh\195\186ng ta \196\145\195\163 chu\225\186\169n b\225\187\139 ng\195\162n s\195\161ch s\225\186\181n s\195\160ng. T\225\186\165t c\225\186\163 nh\225\187\175ng g\195\172 ch\195\186ng ta c\225\186\167n b\195\162y gi\225\187\157 l\195\160 s\225\187\177 ch\225\186\165p thu\225\186\173n c\225\187\167a ng\195\160i. "
L45_1.Text_VTN = L46_1
