L21_1 = "\236\157\180\235\160\135\234\178\140 <color=#ffd34c>\237\143\137\234\176\128\236\132\156</color>\236\153\128 <color=#ffd34c>\237\129\172\235\160\136\235\148\167</color>\235\167\140 \236\158\136\236\156\188\235\169\180\n\236\151\176\235\180\137\237\152\145\236\131\129\236\156\188\235\161\156 \235\185\160\235\165\180\234\178\140 \235\160\136\235\178\168\236\157\132 \235\134\146\236\157\188 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164."
L20_1.Text_KOREA = L21_1
L21_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L20_1.StringValue = L21_1
L21_1 = "\227\129\147\227\129\174\227\130\136\227\129\134\227\129\171\227\128\129<color=#ffd34c>\232\169\149\228\190\161\230\155\184</color>\227\129\168<color=#ffd34c>\227\130\175\227\131\172\227\130\184\227\131\131\227\131\136</color>\227\129\149\227\129\136\227\129\130\227\130\140\227\129\176\227\128\129\n\229\185\180\228\191\184\228\186\164\230\184\137\227\129\167\231\180\160\230\151\169\227\129\143\227\131\172\227\131\153\227\131\171\227\130\146\228\184\138\227\129\146\227\130\139\227\129\147\227\129\168\227\129\140\227\129\167\227\129\141\227\129\190\227\129\153\227\128\130"
L20_1.Text_JPN = L21_1
L21_1 = [[
Like this, you can use <color=#ffd34c>Appraisals</color> and <color=#ffd34c>Credits</color>
to perform Salary Negotiations and level your units.]]
L20_1.Text_ENG = L21_1
L21_1 = "\229\131\143\232\191\153\230\160\183\239\188\140\229\143\170\232\166\129\230\156\137<color=#ffd34c>\233\137\180\229\174\154\228\185\166</color>\229\146\140<color=#ffd34c>\233\135\145\229\184\129</color>\239\188\140\n\229\176\177\232\131\189\233\128\154\232\191\135\229\183\165\232\181\132\229\141\143\229\149\134\229\191\171\233\128\159\230\143\144\233\171\152\231\173\137\231\186\167\227\128\130"
L20_1.Text_SCN = L21_1
L21_1 = "\229\131\143\233\128\153\230\168\163\229\143\170\232\166\129\230\156\137<color=#ffd34c>\233\145\145\229\174\154\230\155\184</color>\229\146\140<color=#ffd34c>\233\135\145\229\185\163</color>\239\188\140\n\229\176\177\229\143\175\228\187\165\233\128\143\233\129\142\232\150\170\232\179\135\229\141\148\229\149\134\229\138\160\233\128\159\229\141\135\231\180\154\229\155\137\239\188\129"
L20_1.Text_TWN = L21_1
L21_1 = "\224\184\149\224\184\178\224\184\161\224\184\153\224\184\181\224\185\137 \224\184\132\224\184\184\224\184\147\224\184\170\224\184\178\224\184\161\224\184\178\224\184\163\224\184\150\224\185\131\224\184\138\224\185\137<color=#ffd34c>\224\185\128\224\184\173\224\184\129\224\184\170\224\184\178\224\184\163\224\184\155\224\184\163\224\184\176\224\185\128\224\184\161\224\184\180\224\184\153</color>\224\185\129\224\184\165\224\184\176<color=#ffd34c>\224\185\128\224\184\132\224\184\163\224\184\148\224\184\180\224\184\149</color>\n\224\185\131\224\184\153\224\184\129\224\184\178\224\184\163\224\184\149\224\185\136\224\184\173\224\184\163\224\184\173\224\184\135\224\184\132\224\185\136\224\184\178\224\184\136\224\185\137\224\184\178\224\184\135\224\185\129\224\184\165\224\184\176\224\185\128\224\184\158\224\184\180\224\185\136\224\184\161\224\185\128\224\184\165\224\185\128\224\184\167\224\184\165\224\184\171\224\184\153\224\185\136\224\184\167\224\184\162\224\184\163\224\184\154"
L20_1.Text_THA = L21_1
L21_1 = "Nh\198\176 v\225\186\173y, ng\195\160i c\195\179 th\225\187\131 s\225\187\173 d\225\187\165ng <color=#ffd34c>\196\144\195\161nh Gi\195\161</color> v\195\160 <color=#ffd34c>Xu V\195\160ng</color>\n\196\145\225\187\131 th\225\187\177c hi\225\187\135n \196\144\195\160m Ph\195\161n L\198\176\198\161ng v\195\160 th\196\131ng c\225\186\165p cho \196\145\198\161n v\225\187\139 c\225\187\167a m\195\172nh."
L20_1.Text_VTN = L21_1
L21_1 = "Auf diese Weise k\195\182nnen Sie <color=#ffd34c>Beurteilungen</color> und <color=#ffd34c>Credits</color> einsetzen, um Gehaltsverhandlungen zu f\195\188hren und Ihre Einheiten aufzustufen."
L20_1.Text_DEU = L21_1
L21_1 = "De cette mani\195\168re, vous pouvez utiliser des <color=#ffd34c>\195\169valuations</color> et <color=#ffd34c>cr\195\169dits</color> pour effectuer des n\195\169gociations de salaire et faire monter vos unit\195\169s de niveau."
L20_1.Text_FRA = L21_1
