L21_1.EventType = "MESSAGE_BOX"
L22_1 = "<color=#ffd34c>\237\143\137\234\176\128\236\132\156</color>\235\165\188 \236\150\187\236\157\132 \236\136\152 \236\158\136\235\138\148 <color=#ffd34c>[\235\170\168\236\157\152\236\158\145\236\160\132-\234\179\181\234\178\169\237\138\185\237\155\136]</color>\236\157\128,\235\167\164\236\157\188 \235\143\132\236\160\132 \237\154\159\236\136\152\234\176\128 \236\180\136\234\184\176\237\153\148 \235\144\152\235\139\136 \234\188\173 \236\157\180\236\154\169\237\149\180 \236\163\188\236\132\184\236\154\148!"
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L21_1.StringValue = L22_1
L22_1 = "<color=#ffd34c>\232\169\149\228\190\161\230\155\184</color>\227\130\146\231\141\178\229\190\151\227\129\167\227\129\141\227\130\139<color=#ffd34c>[\230\168\161\230\147\172\228\189\156\230\136\166\227\131\188\230\148\187\230\146\131\231\137\185\232\168\147]</color>\227\129\175\227\128\129\230\175\142\230\151\165\230\140\145\230\136\166\229\155\158\230\149\176\227\129\140\229\136\157\230\156\159\229\140\150\227\129\149\227\130\140\227\129\190\227\129\153\227\129\174\227\129\167\227\128\129\227\129\156\227\129\178\227\129\148\229\136\169\231\148\168\227\129\143\227\129\160\227\129\149\227\129\132\239\188\129"
L21_1.Text_JPN = L22_1
L22_1 = "<color=#ffd34c>[Simulation - Special Attack Training]</color>, from which you can find <color=#ffd34c>Appraisals</color>, has its Challenge count reset daily. You should try it every day."
L21_1.Text_ENG = L22_1
L22_1 = "<color=#ffd34c>\233\137\180\229\174\154\228\185\166</color>\229\143\175\229\156\168<color=#ffd34c>\227\128\144\230\168\161\230\139\159\228\189\156\230\136\152-\230\148\187\229\135\187\231\137\185\232\174\173\227\128\145</color>\228\184\173\232\142\183\229\143\150\239\188\140\229\133\182\230\140\145\230\136\152\230\172\161\230\149\176\230\175\143\230\151\165\233\131\189\228\188\154\233\135\141\231\189\174\239\188\140\229\155\160\230\173\164\228\184\128\229\174\154\232\166\129\232\174\176\229\190\151\229\143\138\230\151\182\228\189\191\231\148\168\239\188\129"
L21_1.Text_SCN = L22_1
L22_1 = "\229\143\175\231\141\178\229\190\151<color=#ffd34c>\233\145\145\229\174\154\230\155\184</color>\231\154\132<color=#ffd34c>[\230\168\161\230\147\172\230\136\176-\230\148\187\230\147\138\231\137\185\232\168\147]</color>\230\175\143\229\164\169\233\131\189\230\156\131\233\135\141\231\189\174\230\140\145\230\136\176\230\172\161\230\149\184\239\188\140\232\171\139\229\164\154\229\138\160\229\136\169\231\148\168!"
L21_1.Text_TWN = L22_1
L22_1 = "<color=#ffd34c>[\224\184\155\224\184\143\224\184\180\224\184\154\224\184\177\224\184\149\224\184\180\224\184\129\224\184\178\224\184\163\224\184\136\224\184\179\224\184\165\224\184\173\224\184\135 - \224\184\129\224\184\178\224\184\163\224\184\157\224\184\182\224\184\129\224\184\136\224\184\185\224\185\136\224\185\130\224\184\136\224\184\161\224\184\158\224\184\180\224\185\128\224\184\168\224\184\169]</color> \224\184\132\224\184\183\224\184\173\224\184\151\224\184\181\224\185\136\224\184\151\224\184\181\224\185\136\224\184\132\224\184\184\224\184\147\224\184\136\224\184\176\224\184\158\224\184\154<color=#ffd34c>\224\185\128\224\184\173\224\184\129\224\184\170\224\184\178\224\184\163\224\184\155\224\184\163\224\184\176\224\185\128\224\184\161\224\184\180\224\184\153</color> \224\184\151\224\184\181\224\185\136\224\184\153\224\184\181\224\185\136\224\184\161\224\184\181\224\184\129\224\184\178\224\184\163\224\184\163\224\184\181\224\185\128\224\184\139\224\185\135\224\184\149\224\184\136\224\184\179\224\184\153\224\184\167\224\184\153\224\184\129\224\184\178\224\184\163\224\184\151\224\185\137\224\184\178\224\184\151\224\184\178\224\184\162\224\184\151\224\184\184\224\184\129\224\184\167\224\184\177\224\184\153 \224\184\132\224\184\184\224\184\147\224\184\132\224\184\167\224\184\163\224\184\165\224\184\173\224\184\135\224\184\151\224\184\184\224\184\129\224\184\167\224\184\177\224\184\153\224\184\153\224\184\176"
L21_1.Text_THA = L22_1
L22_1 = "<color=#ffd34c>[M\195\180 Ph\225\187\143ng T\195\161c Chi\225\186\191n - \196\144\195\160o T\225\186\161o T\225\186\165n C\195\180ng \196\144\225\186\183c Bi\225\187\135t]</color>, t\225\187\171 \196\145\195\162y, ng\195\160i c\195\179 th\225\187\131 t\195\172m th\225\186\165y <color=#ffd34c>\196\144\195\161nh Gi\195\161</color> v\225\187\155i s\225\187\145 l\198\176\225\187\163t Th\225\187\173 Th\195\161ch \196\145\198\176\225\187\163c \196\145\225\186\183t l\225\186\161i m\225\187\151i ng\195\160y. Ng\195\160i n\195\170n th\225\187\173 s\225\187\169c m\225\187\151i ng\195\160y."
L21_1.Text_VTN = L22_1
L22_1 = "Unter <color=#ffd34c>[Simulation - Spezial-Angriffsausbildung]</color>, wo Sie <color=#ffd34c>Beurteilungen</color> finden, werden die Herausforderungen jeden Tag zur\195\188ckgesetzt. Sie sollten es jeden Tag versuchen."
L21_1.Text_DEU = L22_1
L22_1 = "La cat\195\169gorie <color=#ffd34c>[Simulation - Entra\195\174nement sp\195\169cial \195\160 l'attaque]</color>, dans laquelle vous trouverez les <color=#ffd34c>\195\169valuations</color>, propose des d\195\169fis r\195\169initialis\195\169s quotidiennement. Essayez-les donc chaque jour."
L21_1.Text_FRA = L22_1
