L34_1.Text_ENG = L35_1
L35_1 = "\228\189\156\230\136\152\233\131\168\231\154\132\232\149\190\229\168\156\232\183\159\230\136\145\232\175\180\239\188\140\229\143\175\228\187\165\229\156\168<color=#ffd34c>\232\183\131\229\133\165</color>\228\184\173\232\142\183\229\190\151<color=#ffd34c>\232\136\176\232\136\185\230\157\144\230\150\153</color>\239\188\129\232\175\183\229\164\154\229\164\154\232\191\155\232\161\140\232\183\131\229\133\165\230\180\187\229\138\168\229\144\167\239\188\129"
L34_1.Text_SCN = L35_1
L35_1 = "\228\189\156\230\136\176\233\131\168\231\154\132\232\149\190\229\168\156\232\170\170\239\188\140<color=#ffd34c>\232\137\166\232\136\185\230\157\144\230\150\153</color>\229\143\175\228\187\165\229\156\168<color=#ffd34c>\232\186\141\229\133\165</color>\228\184\173\229\143\150\229\190\151\239\188\140\230\143\144\228\190\155\229\143\131\232\128\131\239\189\158"
L34_1.Text_TWN = L35_1
L35_1 = "\224\185\128\224\184\165\224\184\153\224\185\136\224\184\178\224\184\136\224\184\178\224\184\129\224\185\129\224\184\156\224\184\153\224\184\129\224\184\155\224\184\143\224\184\180\224\184\154\224\184\177\224\184\149\224\184\180\224\184\129\224\184\178\224\184\163\224\184\154\224\184\173\224\184\129\224\184\137\224\184\177\224\184\153\224\184\167\224\185\136\224\184\178\224\184\132\224\184\184\224\184\147\224\184\170\224\184\178\224\184\161\224\184\178\224\184\163\224\184\150\224\184\171\224\184\178<color=#ffd34c>\224\184\167\224\184\177\224\184\170\224\184\148\224\184\184\224\184\162\224\184\178\224\184\153\224\184\163\224\184\154</color>\224\185\132\224\184\148\224\185\137\224\184\136\224\184\178\224\184\129\224\184\129\224\184\178\224\184\163<color=#ffd34c>\224\185\132\224\184\148\224\184\159\224\185\140</color> \224\184\171\224\184\167\224\184\177\224\184\135\224\184\167\224\185\136\224\184\178\224\184\136\224\184\176\224\184\138\224\185\136\224\184\167\224\184\162\224\185\132\224\184\148\224\185\137\224\184\153\224\184\176\224\184\132\224\184\176!"
L34_1.Text_THA = L35_1
L35_1 = "Lena \225\187\159 B\225\187\153 Ph\225\186\173n T\195\161c Chi\225\186\191n n\195\179i v\225\187\155i t\195\180i l\195\160 ng\195\160i c\195\179 th\225\187\131 t\195\172m <color=#ffd34c>C\225\186\165u Ki\225\187\135n T\195\160u</color> th\195\180ng qua <color=#ffd34c>L\225\186\183n</color>. T\195\180i hy v\225\187\141ng l\195\160 n\195\179 c\195\179 hi\225\187\135u qu\225\186\163!"
L34_1.Text_VTN = L35_1
L35_1 = "Lena von der Einsatzabteilung sagte mir, dass man auf <color=#ffd34c>Tauchg\195\164ngen</color> \195\182fter <color=#ffd34c>Schiffskomponenten</color> findet. Hoffentlich hilft das!"
L34_1.Text_DEU = L35_1
