L11_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L10_1.StringValue = L11_1
L11_1 = "\229\183\165\228\186\139\227\129\140\231\181\130\227\130\143\227\129\163\227\129\159\227\129\176\227\129\139\227\130\138\227\129\170\227\129\174\227\129\167\227\128\129\227\129\170\227\130\147\227\129\160\227\129\139\230\174\186\233\162\168\230\153\175\227\129\167\227\129\153\227\129\173\227\128\130"
