L11_1 = "Having just been built, they're completely bare on the inside."
L10_1.Text_ENG = L11_1
L11_1 = "\229\155\160\228\184\186\229\136\154\229\174\140\229\183\165\239\188\140\232\191\152\230\178\161\232\191\155\232\161\140\232\163\133\233\165\176\227\128\130"
