L11_1 = "\224\184\171\224\184\173\224\184\158\224\184\177\224\184\129\224\184\151\224\184\181\224\185\136\224\185\128\224\184\158\224\184\180\224\185\136\224\184\135\224\184\170\224\184\163\224\185\137\224\184\178\224\184\135\224\185\131\224\184\171\224\184\161\224\185\136\224\184\153\224\184\181\224\185\137 \224\184\160\224\184\178\224\184\162\224\185\131\224\184\153\224\184\162\224\184\177\224\184\135\224\185\129\224\184\151\224\184\154\224\185\132\224\184\161\224\185\136\224\184\161\224\184\181\224\184\173\224\184\176\224\185\132\224\184\163\224\185\128\224\184\165\224\184\162"
L10_1.Text_THA = L11_1
L11_1 = "V\225\187\171a m\225\187\155i x\195\162y xong, b\195\170n trong c\195\178n kh\195\161 th\195\180 s\198\161."
