L12_1 = "\227\129\167\227\130\130\229\191\131\233\133\141\227\129\151\227\129\170\227\129\132\227\129\167\227\129\143\227\129\160\227\129\149\227\129\132\227\128\130\227\129\153\227\129\167\227\129\171\231\174\161\231\144\134\233\131\168\227\129\167\229\174\182\229\133\183\227\130\146\230\179\168\230\150\135\227\129\151\227\129\166\227\129\130\227\130\138\227\129\190\227\129\153\227\128\130"
