L9_1.EventType = "MESSAGE_BOX"
L10_1 = "<color=#ffd34c>\237\149\156\234\179\132\234\185\140\236\167\128 \234\176\149\237\149\180\236\167\132 \236\130\172\236\155\144\236\157\132 \236\158\172\235\172\180\236\158\165\236\157\132 \237\134\181\237\149\180 \235\141\148 \234\176\149\237\149\180\236\167\128\234\178\140 \237\149\160 \236\136\152 \236\158\136\236\150\180\236\154\148.</color>"
L9_1.Text_KOREA = L10_1
L10_1 = "AB_INVEN_ICON_NKM_NPC_ASSISTANT_LEE_YOON_JUNG"
L9_1.StringValue = L10_1
L10_1 = "<color=#ffd34c>\233\153\144\231\149\140\227\129\190\227\129\167\229\188\183\227\129\143\227\129\170\227\129\163\227\129\159\231\164\190\229\147\161\227\129\175\229\134\141\230\173\166\232\163\133\227\129\171\227\130\136\227\129\163\227\129\166\227\128\129\227\130\136\227\130\138\229\188\183\227\129\143\227\129\170\227\130\140\227\129\190\227\129\153\227\128\130</color>"
L9_1.Text_JPN = L10_1
L10_1 = "<color=#ffd34c>Now, you can further strengthen your employees through Rearmament after they reach their limits.</color>"
L9_1.Text_ENG = L10_1
L10_1 = "<color=#ffd34c>\229\188\186\229\140\150\229\136\176\230\156\128\229\164\167\229\128\188\231\154\132\232\129\140\229\145\152\239\188\140\229\143\175\228\187\165\233\128\154\232\191\135\229\134\141\230\173\166\232\163\133\232\191\155\228\184\128\230\173\165\229\188\186\229\140\150\227\128\130</color>"
L9_1.Text_SCN = L10_1
L10_1 = "<color=#ffd34c>\232\182\133\232\182\138\230\165\181\233\153\144\233\129\148\229\136\176\230\156\128\233\171\152\233\154\142\230\174\181\231\154\132\229\147\161\229\183\165\239\188\140\229\143\175\228\187\165\232\151\137\231\148\177\229\134\141\230\173\166\232\163\157\232\174\138\229\190\151\230\155\180\229\188\183\227\128\130</color>"
L9_1.Text_TWN = L10_1
L10_1 = "<color=#ffd34c>\224\184\149\224\184\173\224\184\153\224\184\153\224\184\181\224\185\137\224\184\132\224\184\184\224\184\147\224\184\170\224\184\178\224\184\161\224\184\178\224\184\163\224\184\150\224\184\158\224\184\177\224\184\146\224\184\153\224\184\178\224\184\158\224\184\153\224\184\177\224\184\129\224\184\135\224\184\178\224\184\153\224\184\130\224\184\173\224\184\135\224\184\132\224\184\184\224\184\147\224\184\156\224\185\136\224\184\178\224\184\153\224\184\129\224\184\178\224\184\163\224\184\149\224\184\180\224\184\148\224\184\173\224\184\178\224\184\167\224\184\184\224\184\152\224\185\131\224\184\171\224\184\161\224\185\136\224\184\171\224\184\165\224\184\177\224\184\135\224\184\136\224\184\178\224\184\129\224\184\151\224\184\181\224\185\136\224\184\158\224\184\167\224\184\129\224\185\128\224\184\130\224\184\178\224\184\150\224\184\182\224\184\135\224\184\130\224\184\181\224\184\148\224\184\136\224\184\179\224\184\129\224\184\177\224\184\148</color>"
L9_1.Text_THA = L10_1
L10_1 = "<color=#ffd34c>Gi\225\187\157 \196\145\195\162y, ng\195\160i c\195\179 th\225\187\131 t\196\131ng c\198\176\225\187\157ng s\225\187\169c m\225\186\161nh cho nh\195\162n vi\195\170n c\225\187\167a m\195\172nh h\198\161n n\225\187\175a th\195\180ng qua t\195\161i v\197\169 trang sau khi h\225\187\141 \196\145\225\186\161t \196\145\225\186\191n gi\225\187\155i h\225\186\161n c\225\187\167a m\195\172nh.</color>"
L9_1.Text_VTN = L10_1
L10_1 = "<color=#ffd34c>Jetzt k\195\182nnen Sie Mitarbeiter, die ihr Limit erreicht haben, durch Wiederbewaffnung noch st\195\164rker machen.</color>"
L9_1.Text_DEU = L10_1
L10_1 = "<color=#ffd34c>Vous pouvez maintenant renforcer davantage vos employ\195\169s, m\195\170me apr\195\168s qu'ils aient atteint leur limite, et ce, gr\195\162ce au r\195\169armement.</color>"
L9_1.Text_FRA = L10_1
